fn base_p_digits(mut rank: Rank) -> [u32; 8] {
    core::array::from_fn(|_| {
        let mut remainder = 0u64;
        for limb in rank.iter_mut().rev() {
            let dividend = (remainder << 32) | u64::from(*limb);
            *limb = (dividend / u64::from(P)) as u32;
            remainder = dividend % u64::from(P);
        }
        remainder as u32
    })
}

fn decode4([a, b, c, d]: [u32; 4]) -> QM31 {
    QM31 {
        c0: CM31::new(M31(a), M31(b)),
        c1: CM31::new(M31(c), M31(d)),
    }
}

fn decode8([a, b, c, d, e, f, g, h]: [u32; 8]) -> WideExact {
    // R-A's constructor, with already canonical base-P digits. No fallible
    // decoder or unwrap on the sampler's total path.
    WideExact::new(decode4([a, b, c, d]), decode4([e, f, g, h]))
}

/// `decode4(digits(rank(block) mod P^4))`, exactly `SemD2.qm31Sample`.
pub fn qm31_sample(block: &[u8; 32]) -> QM31 {
    let d = base_p_digits(reduce_rank(block_rank(block), P4));
    decode4([d[0], d[1], d[2], d[3]])
}

pub fn build_copy_logup_helper(rows: &[CopyLogUpRow], chi: QM31) -> Result<Vec<QM31>, LogUpError> {
    let mut helper = Vec::with_capacity(rows.len());
    for (row_index, row) in rows.iter().enumerate() {
        let mut value = QM31::ZERO;
        for (producer_value, weight) in row.producer_values.into_iter().zip(row.producer_weights) {
            if weight != M31::ZERO {
                value = value.add(
                    chi.sub(producer_value)
                        .try_inv()
                        .ok_or(LogUpError::ActivePole {
                            row: row_index,
                            side: LogUpSide::Producer,
                        })?
                        .mul_m31(weight),
                );
            }
        }
        for (consumer_value, weight) in row.consumer_values.into_iter().zip(row.consumer_weights) {
            if weight != M31::ZERO {
                value = value.sub(
                    chi.sub(consumer_value)
                        .try_inv()
                        .ok_or(LogUpError::ActivePole {
                            row: row_index,
                            side: LogUpSide::Consumer,
                        })?
                        .mul_m31(weight),
                );
            }
        }
        helper.push(value);
    }
    Ok(helper)
}

